package com.olunaa.app;

import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

public class AdminActivity extends Activity {
 private static final String API="https://olunaa.vercel.app/api";private static final int BG=Color.rgb(7,13,28),CARD=Color.rgb(13,22,43),FIELD=Color.rgb(17,31,56),WHITE=Color.rgb(248,248,255),MUTED=Color.rgb(175,177,214),PURPLE=Color.rgb(67,139,255),MAGENTA=Color.rgb(42,91,232),CYAN=Color.rgb(80,190,255);private final ExecutorService io=Executors.newCachedThreadPool();private final Handler main=new Handler(Looper.getMainLooper());private android.content.SharedPreferences prefs;private LinearLayout root,content;private String cookie="";
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private GradientDrawable box(int[] c){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,c);g.setCornerRadius(dp(22));g.setStroke(1,Color.rgb(55,100,170));return g;}private TextView tv(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setMinHeight(0);b.setBackground(box(new int[]{PURPLE,MAGENTA,CYAN}));return b;}private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(MUTED);e.setTextColor(WHITE);e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(16),0,dp(16),0);e.setBackground(box(new int[]{FIELD,Color.rgb(20,20,58)}));return e;}private LinearLayout.LayoutParams lp(int h,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,h);p.setMargins(0,0,0,dp(b));return p;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);prefs=getSharedPreferences("olunaa_admin",MODE_PRIVATE);cookie=prefs.getString("cookie","");if(cookie.isEmpty())login();else dashboard();}
 private void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(12),dp(14),dp(12));root.setBackgroundColor(BG);setContentView(root);}private void login(){base();LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setGravity(Gravity.CENTER_HORIZONTAL);b.setPadding(dp(10),dp(45),dp(10),dp(20));root.addView(b,new LinearLayout.LayoutParams(-1,-1));TextView x=tv("◈",64,CYAN);x.setGravity(Gravity.CENTER);b.addView(x,lp(dp(80),10));TextView h=tv("OLUNAA ADMIN",30,WHITE);h.setTypeface(null,1);b.addView(h,lp(-2,4));b.addView(tv("Full control center • protected access",14,MUTED),lp(-2,28));LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(20),dp(22),dp(20),dp(22));c.setBackground(box(new int[]{CARD,Color.rgb(10,24,48)}));b.addView(c,lp(-2,15));EditText u=input("Admin username"),p=input("Admin password");p.setInputType(0x81);c.addView(u,lp(dp(54),10));c.addView(p,lp(dp(54),15));Button go=btn("Secure sign in");c.addView(go,new LinearLayout.LayoutParams(-1,dp(54)));go.setOnClickListener(v->{go.setEnabled(false);JSONObject j=new JSONObject();try{j.put("username",u.getText().toString().trim());j.put("password",p.getText().toString());}catch(Exception ignored){}api("/admin/login","POST",j,true,r->{go.setEnabled(true);if(!r.ok){toast(r.error);return;}dashboard();});});Button back=btn("Back to OLUNAA");b.addView(back,lp(dp(52),0));back.setOnClickListener(v->finish());}
 private void dashboard(){base();LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);TextView t=tv("OLUNAA ADMIN",23,WHITE);t.setTypeface(null,1);h.addView(t,new LinearLayout.LayoutParams(0,dp(52),1));Button refresh=btn("Refresh");h.addView(refresh,new LinearLayout.LayoutParams(dp(105),dp(48)));root.addView(h,lp(dp(56),8));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout tabs=new LinearLayout(this);String[] ts={"Overview","Users","Channels"};for(String s:ts){Button q=btn(s);tabs.addView(q,new LinearLayout.LayoutParams(0,dp(52),1));q.setOnClickListener(v->{if(s.equals("Overview"))overview();else if(s.equals("Users"))users();else channels();});}root.addView(tabs,lp(dp(58),0));refresh.setOnClickListener(v->overview());overview();}
 private void clear(){content.removeAllViews();}private void title(String h,String s){TextView a=tv(h,25,WHITE);a.setTypeface(null,1);content.addView(a,lp(-2,4));content.addView(tv(s,13,MUTED),lp(-2,14));}private void stat(String k,String v){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(15),dp(13),dp(15),dp(13));c.setBackground(box(new int[]{CARD,Color.rgb(10,24,48)}));TextView n=tv(v,27,WHITE);n.setTypeface(null,1);c.addView(n);c.addView(tv(k,12,MUTED));content.addView(c,lp(dp(86),7));}
 private void overview(){clear();title("Command center","Live platform data and operational controls");api("/admin/overview","GET",null,false,r->{if(!r.ok){toast(r.error);return;}JSONObject s=r.data.optJSONObject("stats");if(s==null)return;String[][] a={{"Total users","users"},{"Active in 24h","active24h"},{"Conversations","conversations"},{"Messages","messages"},{"Stories","stories"},{"Groups","groups"},{"Channels","channels"},{"Notifications","notifications"},{"Live sessions","sessions"}};for(String[] x:a)stat(x[0],s.optString(x[1],"0"));content.addView(tv("Recent users",18,CYAN),lp(-2,12));JSONArray u=r.data.optJSONArray("recentUsers");if(u!=null)for(int i=0;i<u.length();i++){JSONObject z=u.optJSONObject(i);if(z!=null)userCard(z,false);}});}
 private void users(){clear();title("Users","Search, verify or revoke sessions");EditText q=input("Search name, @username or email");content.addView(q,lp(dp(54),10));Button go=btn("Search users");content.addView(go,lp(dp(50),12));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Runnable load=()->api("/admin/users?q="+URLEncoder.encode(q.getText().toString().trim(),StandardCharsets.UTF_8),"GET",null,false,r->{list.removeAllViews();if(!r.ok){toast(r.error);return;}JSONArray a=r.data.optJSONArray("users");if(a!=null)for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);if(u!=null)userCardInto(list,u,true);}});go.setOnClickListener(v->load.run());load.run();}
 private void userCard(JSONObject u,boolean c){userCardInto(content,u,c);}private void userCardInto(LinearLayout list,JSONObject u,boolean controls){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(14),dp(13),dp(14),dp(13));c.setBackground(box(new int[]{CARD,Color.rgb(10,24,48)}));TextView n=tv(u.optString("displayName","User")+(u.optBoolean("verified")?"  ✓":""),17,WHITE);n.setTypeface(null,1);c.addView(n);c.addView(tv("@"+u.optString("username","")+" • "+u.optString("email",""),12,MUTED));if(controls){LinearLayout a=new LinearLayout(this);Button v=btn(u.optBoolean("verified")?"Unverify":"Verify"),r=btn("Revoke sessions"),del=btn("Delete user");a.addView(v,new LinearLayout.LayoutParams(0,dp(48),1));a.addView(r,new LinearLayout.LayoutParams(0,dp(48),1));a.addView(del,new LinearLayout.LayoutParams(0,dp(48),1));c.addView(a);v.setOnClickListener(x->{JSONObject j=new JSONObject();try{j.put("userId",u.optString("id"));j.put("verified",!u.optBoolean("verified"));}catch(Exception ignored){}api("/admin/users","PATCH",j,false,z->{if(z.ok)users();else toast(z.error);});});r.setOnClickListener(x->{JSONObject j=new JSONObject();try{j.put("userId",u.optString("id"));j.put("action","revoke-sessions");}catch(Exception ignored){}api("/admin/users","DELETE",j,false,z->toast(z.ok?"Sessions revoked.":z.error));});del.setOnClickListener(x->new AlertDialog.Builder(this).setTitle("Delete account?").setMessage("This permanently deletes @"+u.optString("username")+" and related account data.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(dialog,which)->{JSONObject j=new JSONObject();try{j.put("userId",u.optString("id"));j.put("action","delete-user");}catch(Exception ignored){}api("/admin/users","DELETE",j,false,z->{toast(z.ok?"User deleted.":z.error);if(z.ok)users();});}).show());}list.addView(c,lp(-2,8));}
 private void channels(){clear();title("Channels & announcements","Publish official posts or remove channels");EditText n=input("Channel name"),h=input("Public channel number e.g. +49991"),b=input("Official announcement");b.setSingleLine(false);b.setMinHeight(dp(110));content.addView(n,lp(dp(54),7));content.addView(h,lp(dp(54),7));content.addView(b,lp(dp(110),10));Button p=btn("Publish official post");content.addView(p,lp(dp(52),14));p.setOnClickListener(v->{JSONObject j=new JSONObject();try{j.put("name",n.getText().toString().trim());j.put("channelNumber",h.getText().toString().trim());j.put("body",b.getText().toString().trim());}catch(Exception ignored){}api("/admin/channels","POST",j,false,r->{toast(r.ok?"Published.":r.error);if(r.ok)channels();});});api("/admin/channels","GET",null,false,r->{if(!r.ok){toast(r.error);return;}JSONArray a=r.data.optJSONArray("channels");if(a!=null)for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);if(c==null)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),dp(12),dp(14),dp(12));row.setBackground(box(new int[]{CARD,Color.rgb(10,24,48)}));JSONObject co=c.optJSONObject("_count");row.addView(tv(c.optString("name","Channel")+"  ✓\n"+(c.optString("channelNumber","").isEmpty()?"@"+c.optString("handle",""):c.optString("channelNumber",""))+" • "+(co==null?0:co.optInt("members"))+" members • "+(co==null?0:co.optInt("messages"))+" posts",15,WHITE),new LinearLayout.LayoutParams(0,dp(74),1));Button d=btn("Delete");row.addView(d,new LinearLayout.LayoutParams(dp(90),dp(48)));d.setOnClickListener(v->{JSONObject j=new JSONObject();try{j.put("channelId",c.optString("id"));}catch(Exception ignored){}api("/admin/channels","DELETE",j,false,z->{if(z.ok)channels();else toast(z.error);});});content.addView(row,lp(dp(84),7));}});}
 private void api(String path,String method,JSONObject body,boolean capture,Callback cb){io.execute(()->{Result out;try{HttpURLConnection c=(HttpURLConnection)new URL(API+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");if(!cookie.isEmpty())c.setRequestProperty("Cookie",cookie);if(body!=null&&!method.equals("GET")){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();String set=c.getHeaderField("Set-Cookie");if(capture&&set!=null){cookie=set.split(";",2)[0];prefs.edit().putString("cookie",cookie).apply();}InputStream in=code>=400?c.getErrorStream():c.getInputStream();String raw=read(in);c.disconnect();JSONObject d=raw.isEmpty()?new JSONObject():new JSONObject(raw);out=new Result(code>=200&&code<300,d.optString("error","Request failed ("+code+")"),d);}catch(Exception e){out=new Result(false,"Connection error",new JSONObject());}Result rr=out;main.post(()->cb.done(rr));});}private String read(InputStream in)throws Exception{if(in==null)return "";BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String x;while((x=r.readLine())!=null)s.append(x);r.close();return s.toString();}private interface Callback{void done(Result r);}private static class Result{boolean ok;String error;JSONObject data;Result(boolean a,String b,JSONObject c){ok=a;error=b;data=c;}}private void toast(String s){main.post(()->Toast.makeText(this,s,Toast.LENGTH_SHORT).show());}
}
